public class SafeBufferImplementation {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        int bufferSize = 10;
        char[] buffer = new char[bufferSize]; // Buffer size is fixed to 10

        // Copy user input into buffer with proper bounds checking
        int length = Math.min(userInput.length(), bufferSize); // Ensure we do not copy more than buffer size
