import java.util.Arrays;

public class SecureBuffer {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        int bufferSize = 10;
        char[] buffer = new char[bufferSize]; // Buffer of fixed size

        // Copy user input into the buffer with proper bounds checking
        int length = Math.min(input.length(), bufferSize); // Ensure not to exceed buffer size
        Arrays.copyOf(input.toCharArray(), length, buffer, 0); // Copy input to buffer

        // Print the contents of the buffer
        System.out.println("Buffer contents: " + new String(buffer));
    }
}

