import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SafePathTraversal {

    public static void main(String[] args) throws IOException {
        String userInput = "../../some_sensitive_file.txt";
        String basePath = "/home/user/documents/";

        // Use Paths.get() to safely resolve the file path
        Path resolvedPath = Paths.get(basePath).resolve(userInput).normalize();

        // Check if resolvedPath is within basePath
        if (!resolvedPath.startsWith(Paths.get(basePath))) {
            System.out.println("Invalid file path.");
            return;
        }

        File file = resolvedPath.toFile();

        if (file.exists()) {
            byte[] fileContent = Files.readAllBytes(file.toPath());
            System.out.println(new String(fileContent));
        } else {
            System.out.println("File not found.");
        }
    }
}

