        // Loop through each token
        AutoPilot tokAp = new AutoPilot(vn);
        tokAp.selectElement(AgigaConstants.TOKEN);
        while (tokAp.iterate()) {
            // Just double check that the tokens are in order
            if (tokId < 0) {
