import java.util.Scanner;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        int bufferSize = 10;
        char[] buffer = new char[bufferSize]; // Buffer size is limited to 10 characters

        if (userInput.length() > bufferSize) {
            System.out.println("Input exceeds buffer size. Truncating to fit buffer.");
            userInput = userInput.substring(0, bufferSize);
        }

        userInput.getChars(0, userInput.length(), buffer, 0); // Copy user input into buffer

        System.out.println("Buffer contents: " + new String(buffer));
    }
}

