import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class XSSFixedServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");

        // Properly sanitize and encode user input before outputting it to the response
        String sanitizedInput = sanitizeInput(userInput);

        PrintWriter out = response.getWriter();
        out.println("<html><body>User Input: " + sanitizedInput + "</body></html>");
    }

    private String sanitizeInput(String input) {
        // Perform proper input validation and encoding to prevent XSS attacks
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;")
                    .replace("/", "&#x2F;");
    }
}

