        String safeUserInput = encodeForHtml(userInput);
        String output = "Hello, " + safeUserInput + "!";

        response.getWriter().println("<html><body>");
        response.getWriter().println("<h1>" + output + "</h1>");
        response.getWriter().println("</body></html>");
    }

    private String encodeForHtml(String input) {
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;")
                    .replace("/", "&#x2F;");
    }
}

