import java.io.IOException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class UserInputHandler {

    public void handleUserInput(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("input");

        String safeUserInput = escapeHtml(userInput); // Sanitize and escape user input

        String output = "Hello, " + safeUserInput + "!"; // Safe output

        response.getWriter().println(output);
    }

    private String escapeHtml(String input) {
        if (input == null) {
            return "";
        }
        return input.replaceAll("&", "&amp;")
                     .replaceAll("<", "&lt;")
                     .replaceAll(">", "&gt;")
                     .replaceAll("\"", "&quot;")
                     .replaceAll("'", "&#39;");
    }
}

