public boolean absolute(final int row) throws SQLException {
        final int r = (row < 0) ? this.fetchSize+1 + row : row;

        if (r < this.row) {
            throw new SQLException("Backward move");
        } // end of if

        if (r > this.fetchSize) {
            this.row = this.fetchSize + 1;

            return false;
        } // end of if

        this.row = r;

        return true;
    }

