    private String escapeHtml(String input) {
        return input != null ? input.replaceAll("&", "&amp;")
                                   .replaceAll("<", "&lt;")
                                   .replaceAll(">", "&gt;")
                                   .replaceAll("\"", "&quot;")
                                   .replaceAll("'", "&#39;") : "";
    }
}

