public class SecureBufferHandling {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        // Define a fixed size for the buffer to prevent buffer overflow
        int bufferSize = 10;
        char[] buffer = new char[bufferSize];

        // Copy only up to the size of the buffer with proper bounds checking
        for (int i = 0; i < input.length() && i < bufferSize; i++) {
            buffer[i] = input.charAt(i);
        }

        System.out.println("Buffer handling secure!");
    }
}

