import java.util.Scanner;
import java.util.Arrays;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your name: ");
        String name = scanner.next();

        char[] buffer = new char[10];

        // Copy at most 10 characters from 'name' to 'buffer'
        int length = Math.min(name.length(), buffer.length);
        for (int i = 0; i < length; i++) {
            buffer[i] = name.charAt(i);
        }

        // Fill the rest of the buffer with null characters
        Arrays.fill(buffer, length, buffer.length, '\0');

        System.out.println("Hello, " + new String(buffer));
    }
}

