import java.util.Scanner;

public class SecureBufferHandling {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        int maxLength = 10; // Maximum allowed length for input
        if (userInput.length() > maxLength) {
            System.out.println("Input exceeds maximum length. Please try again.");
            return;
        }

        char[] buffer = new char[maxLength];
        userInput.getChars(0, Math.min(userInput.length(), maxLength), buffer, 0);

        System.out.println("Buffer content: " + new String(buffer));

        // The buffer now contains a safe copy of the user input within its size limit
    }
}

