        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine(); // Use nextLine() to read the entire line

        char[] buffer = new char[10];

        // Copy the input string to buffer without exceeding its size
        int length = Math.min(userInput.length(), buffer.length);
        userInput.getChars(0, length, buffer, 0);

        // Fill the rest of the buffer with zeros if needed
        if (userInput.length() < buffer.length) {
            Arrays.fill(buffer, userInput.length(), buffer.length, '\0');
        }

        System.out.println("Buffer content: " + new String(buffer));
