    private String sanitizeInput(String userInput) {
        // Replace special characters with HTML entities to prevent XSS
        userInput = userInput.replace("&", "&amp;")
                             .replace("<", "&lt;")
                             .replace(">", "&gt;")
                             .replace("\"", "&quot;")
                             .replace("'", "&#39;");

        return userInput;
    }
}

