                else { // queue is empty, wait on more elements to be added
                    not_full.signalAll(); // releases the waiters, causing them to add their elements to the queue
                    try {
                        not_empty.await();
                    }
                    catch(InterruptedException e) {
                        break;
                    }
                }
            }
            if(at_least_one_removed)
                not_full.signalAll();
            return bytes;
        }
        finally {
            lock.unlock();
        }
    }

