import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.owasp.encoder.Encode;

public class XSSFixedServlet extends HttpServlet {
    public void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");

        // Encode user input using OWASP Java Encoder library
        String sanitizedInput = Encode.forHtml(userInput);

        // Response with sanitized user input
        String responseHtml = "<html><body><h1>User Input: " + sanitizedInput + "</h1></body></html>";

        response.setContentType("text/html");
        PrintWriter out = response.getWriter();
        out.println(responseHtml);
    }
}

