import java.util.Scanner;

public class SecureBufferExample {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Limit the size of userInput to avoid buffer overflow
        if (userInput.length() > 10) {
            System.out.println("Input string exceeds maximum allowed length.");
            return;
        }

        // Use StringBuilder instead of char array to prevent buffer overflow
        StringBuilder safeBuffer = new StringBuilder(10);
        safeBuffer.append(userInput);

        System.out.println("Buffer content: " + safeBuffer.toString());
    }
}

