public class SecureBuffer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Ensure that the buffer size matches or exceeds the input length
        char[] buffer = new char[Math.min(10, name.length())];

        // Safely copy characters into the buffer with bounds checking
        System.arraycopy(name.toCharArray(), 0, buffer, 0, buffer.length);

        System.out.println("Hello, " + new String(buffer));
    }
}

